/// The names Evora supplies a drawing for, in the table's order (`diag.ui`, smoke test ICONS).
pub fn names() -> Vec<&'static str> {
    ICONS.iter().map(|(name, _)| *name).collect()
}

/// Paint Evora's pictogram `name` into `r`, centred, in colour `c`. `false`: Evora has no drawing for
/// `name` (the upstream one is used).
pub fn paint(p: &Painter, r: Rect, name: &str, c: Color32) -> bool {
    let Some((_, subs)) = ICONS.iter().find(|(n, _)| *n == name) else {
        return false;
    };
    let s = r.width().min(r.height()) / GRID;
    let o = r.center() - vec2(GRID / 2.0 * s, GRID / 2.0 * s);
    let at = |q: &(f32, f32)| -> Pos2 { pos2(o.x + q.0 * s, o.y + q.1 * s) };
    let stroke = Stroke::new(STROKE * s, c);
    for (closed, pts) in subs.iter() {
        if pts.len() == 1 {
            p.circle_filled(at(&pts[0]), DOT_RADIUS * s, c);
            continue;
        }
        let v: Vec<Pos2> = pts.iter().map(|q| at(q)).collect();
        p.add(if *closed { Shape::closed_line(v, stroke) } else { Shape::line(v, stroke) });
    }
    true
}
